SELECT is_remote, CASE WHEN salary >= 130000 THEN 'high' WHEN salary >= 45000 THEN 'mid' ELSE 'low' END AS salary_bucket, COUNT(DISTINCT salary) AS unique_managers, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(level))) AS level_values FROM employees GROUP BY is_remote, CASE WHEN salary >= 130000 THEN 'high' WHEN salary >= 45000 THEN 'mid' ELSE 'low' END ORDER BY salary_bucket, unique_managers DESC;
